WORD __thiscall CHARACTER::GetRaceNum(CHARACTER *this)

{
  WORD WVar1;
  
  if (this->m_dwPolymorphRace == 0) {
    if (this->m_pkMobData == (CMob *)0x0) {
      WVar1 = (WORD)(this->m_points).job;
    }
    else {
      WVar1 = (WORD)(this->m_pkMobData->m_table).dwVnum;
    }
  }
  else {
    WVar1 = (WORD)this->m_dwPolymorphRace;
  }
  return WVar1;
}
